package dev.underthebedrock.horror;
import dev.underthebedrock.UnderTheBedrockPlugin;import dev.underthebedrock.world.VoidWorldManager;import org.bukkit.Location;import org.bukkit.Sound;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import io.papermc.paper.event.player.AsyncChatEvent;import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;import org.bukkit.event.player.PlayerQuitEvent;import org.bukkit.scheduler.BukkitTask;import java.util.EnumMap;import java.util.HashMap;import java.util.Locale;import java.util.Map;import java.util.Optional;import java.util.Random;import java.util.UUID;
/** Per-player pacing, memory, contextual Null reactions, and the central entity encounter gate. */
public final class OccurrenceDirector implements Listener {
 private final long intervalTicks,minGapMs,severeGapMs,entityCooldownMs;private final double rollChance;private final EntityEncounterPolicy entityPolicy;private final NullIntelligence nullAI=new NullIntelligence();private final UnderTheBedrockPlugin plugin;private final VoidWorldManager worlds;private final PlayerHorrorMemoryStore store;private final Map<UUID,PlayerHorrorMemory> memories=new HashMap<>();private final Map<UUID,Location> lastLocations=new HashMap<>();private final Map<UUID,Map<String,Long>> behaviorCooldowns=new HashMap<>();private final Random random=new Random();private BukkitTask task;
 public OccurrenceDirector(UnderTheBedrockPlugin p,VoidWorldManager w,PlayerHorrorMemoryStore s){plugin=p;worlds=w;store=s;intervalTicks=Math.max(1,p.getConfig().getLong("horror.director.check-interval-seconds",12))*20L;minGapMs=Math.max(1,p.getConfig().getLong("horror.director.minimum-occurrence-gap-seconds",42))*1000L;severeGapMs=Math.max(1,p.getConfig().getLong("horror.director.severe-occurrence-cooldown-minutes",8))*60000L;entityCooldownMs=Math.max(1,p.getConfig().getLong("horror.entities.successful-encounter-cooldown-minutes",8))*60000L;rollChance=Math.max(0,Math.min(1,p.getConfig().getDouble("horror.director.base-roll-chance",.22)));entityPolicy=new EntityEncounterPolicy(p.getConfig().getDouble("horror.entities.safe-radius-blocks",512),p.getConfig().getDouble("horror.entities.full-threat-distance-blocks",8192),p.getConfig().getDouble("horror.entities.maximum-chance-per-check",.025));}
 public void start(){if(task!=null)return;plugin.getServer().getPluginManager().registerEvents(this,plugin);task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,intervalTicks,intervalTicks);}
 public void stop(){if(task!=null)task.cancel();task=null;for(var e:memories.entrySet())store.save(e.getKey(),e.getValue());memories.clear();lastLocations.clear();behaviorCooldowns.clear();}
 public PlayerHorrorMemory memory(UUID id){return memories.computeIfAbsent(id,store::load);}public void saveMemory(UUID id){PlayerHorrorMemory m=memories.get(id);if(m!=null)store.save(id,m);}
 public int recordBehavior(Player player,String behavior){PlayerHorrorMemory m=memory(player.getUniqueId());long now=System.currentTimeMillis();long cooldown=behavior.equals("built_shelter")?20000L:behavior.equals("destroyed_ancient_site")||behavior.equals("stole_artifact")?5000L:1500L;Map<String,Long> cooldowns=behaviorCooldowns.computeIfAbsent(player.getUniqueId(),ignored->new HashMap<>());Long previous=cooldowns.get(behavior);if(previous!=null&&now-previous<cooldown)return m.behaviorCount(behavior);cooldowns.put(behavior,now);int count=m.recordBehavior(behavior);m.addTension(behavior.equals("destroyed_ancient_site")?1.4:behavior.equals("recovered_artifact")?0.8:0.35);if(behavior.equals("destroyed_ancient_site")||behavior.equals("stole_artifact"))m.provoke(1.5);saveMemory(player.getUniqueId());return count;}
 public String status(Player p){PlayerHorrorMemory m=memory(p.getUniqueId());return String.format(Locale.ROOT,"§7Chapter: §f%s §8| §7Tension: §f%.1f §8| §7Events: §f%d",StoryChapter.forPlayer(m),m.tension(),m.encounters());}
 public Optional<EntityArchetype> trySelectEntityEncounter(Player p){if(!worlds.isActive()||!p.getWorld().equals(worlds.getWorld()))return Optional.empty();Location s=worlds.getWorld().getSpawnLocation();double d=Math.hypot(p.getLocation().getX()-s.getX(),p.getLocation().getZ()-s.getZ());PlayerHorrorMemory m=memory(p.getUniqueId());if(System.currentTimeMillis()-m.lastEntityEncounterAt()<entityCooldownMs)return Optional.empty();return entityPolicy.roll(d,random,m);}
 public void recordEntityEncounter(Player p,EntityArchetype type){PlayerHorrorMemory m=memory(p.getUniqueId());m.recordEntity(type,System.currentTimeMillis());saveMemory(p.getUniqueId());}
 public double entityChanceAt(Player p){if(!worlds.isActive()||!p.getWorld().equals(worlds.getWorld()))return 0;Location s=worlds.getWorld().getSpawnLocation();return entityPolicy.chanceAt(Math.hypot(p.getLocation().getX()-s.getX(),p.getLocation().getZ()-s.getZ()));}
 private void tick(){if(!worlds.isActive())return;var w=worlds.getWorld();if(w==null)return;long now=System.currentTimeMillis();for(Player p:w.getPlayers()){PlayerHorrorMemory m=memory(p.getUniqueId());Location c=p.getLocation(),prev=lastLocations.put(p.getUniqueId(),c.clone());if(prev!=null&&prev.getWorld().equals(c.getWorld()))m.addDistance((long)Math.sqrt(prev.distanceSquared(c)));m.relax();if(now-m.lastOccurrenceAt()<minGapMs||random.nextDouble()>rollChance)continue;deliver(p,m,chooseSeverity(m,now),now);if(m.encounters()%3==0)saveMemory(p.getUniqueId());}}
 private OccurrenceSeverity chooseSeverity(PlayerHorrorMemory m,long now){Map<OccurrenceSeverity,Double> weights=new EnumMap<>(OccurrenceSeverity.class);boolean ready=now-m.lastSevereOccurrenceAt()>=severeGapMs;StoryChapter c=StoryChapter.forPlayer(m);double total=0;for(OccurrenceSeverity s:OccurrenceSeverity.values()){double v=s.baseWeight()*(1+(m.tension()/100)*s.rank()*.7)*(1+(m.provocation()/100)*s.rank()*.9);if(s.rank()>=4&&!ready)v=0;if(s==OccurrenceSeverity.TERRIFYING&&(m.tension()<70||m.provocation()<45||c.ordinal()<StoryChapter.NULL_INFLUENCE.ordinal()))v=0;weights.put(s,v);total+=v;}double roll=random.nextDouble()*total;for(OccurrenceSeverity s:OccurrenceSeverity.values()){roll-=weights.get(s);if(roll<=0)return s;}return OccurrenceSeverity.NORMAL;}
 private void deliver(Player p,PlayerHorrorMemory m,OccurrenceSeverity s,long now){switch(s){
 case NORMAL->{if(random.nextBoolean())p.playSound(p.getLocation(),Sound.AMBIENT_CAVE,.16f,.75f);}
 case ODD->p.playSound(p.getLocation(),Sound.BLOCK_WOODEN_DOOR_OPEN,.22f,.65f);
 case STRANGE->{p.playSound(p.getLocation().subtract(p.getLocation().getDirection().multiply(5)),Sound.BLOCK_STONE_STEP,.42f,.72f);if(m.discoveredClueCount()>0)p.sendMessage("§8The marks are not where you left them.");}
 case WEIRD->{p.playSound(p.getLocation(),Sound.ENTITY_ENDERMAN_STARE,.28f,.65f);p.sendMessage(m.discoveredClueCount()>=2?"§8Someone has added a line to the evidence.":"§8You get the feeling something was just here.");}
 case SCARY->{p.playSound(p.getLocation(),Sound.ENTITY_WARDEN_HEARTBEAT,.24f,.8f);p.sendMessage(m.discoveredClueCount()>=3?"§8You hear three quiet knocks. The recording had three, too.":"§8For a moment, the darkness feels occupied.");}
 case TERRIFYING->{p.playSound(p.getLocation(),Sound.ENTITY_WARDEN_HEARTBEAT,.5f,.55f);p.sendMessage(m.discoveredClueCount()>=5?"§8§oYou brought the last piece here. It was already waiting.":"§8§oIt knows you are looking.");}
 }m.recordOccurrence("story_"+s.name().toLowerCase(Locale.ROOT),s,now);}
 @EventHandler public void onChat(AsyncChatEvent e){String message=PlainTextComponentSerializer.plainText().serialize(e.message());UUID id=e.getPlayer().getUniqueId();String t=message.toLowerCase(Locale.ROOT);double amount=0;if(has(t,"null","where are you","come here","show yourself"))amount+=2.5;if(has(t,"hate you","stupid","kill you","you can't","coward","i will destroy you","you are lying","liar"))amount+=5;if(has(t,"i am not scared","not afraid","i know you're there","are you scared","are you afraid"))amount+=3;if(amount<=0&&!has(t,"hello","hi null","anyone there","what did i find","do you remember","evidence","i miss them","i miss everyone","i forgive you","i am sorry","you are lying","liar","are you scared","are you afraid","i can help you","let me help","we can fix this","you know who i am","you changed the record","what do you remember about me","what do you know about me","what have i done","do you trust me","i trust you"))return;double provocation=amount;plugin.getServer().getScheduler().runTask(plugin,()->{Player p=plugin.getServer().getPlayer(id);if(p==null||!worlds.isActive()||!p.getWorld().equals(worlds.getWorld())||!isWithinNullRange(p))return;PlayerHorrorMemory m=memory(id);if(provocation>0){m.provoke(provocation);m.addTension(1.2);}if(has(t,"i can help you","let me help","we can fix this"))m.recordBehavior("offered_help");if(has(t,"i miss them","i miss everyone","they were my friends"))m.recordBehavior("grieved_for_residents");if(has(t,"i forgive you","i forgive","i am sorry"))m.recordBehavior("forgave_null");if(has(t,"you are lying","liar","that is not true"))m.recordBehavior("accused_null");if(has(t,"i will destroy you","kill you","hate you"))m.recordBehavior("threatened_null");if(has(t,"do you trust me","i trust you"))m.recordBehavior("asked_for_trust");m.recordChat(System.currentTimeMillis());nullAI.respond(p,message,m).ifPresent(response->{if(random.nextDouble()<responseChance(m)){p.sendMessage(response);m.addTension(.8);p.playSound(p.getLocation(),Sound.ENTITY_ENDERMAN_STARE,.22f,.55f);}});saveMemory(id);});}
 private boolean isWithinNullRange(Player p){Location spawn=worlds.getWorld().getSpawnLocation();double distance=Math.hypot(p.getLocation().getX()-spawn.getX(),p.getLocation().getZ()-spawn.getZ());double minimum=Math.max(0,plugin.getConfig().getDouble("horror.null.minimum-distance-blocks",1000));return distance>=minimum;}
 private double responseChance(PlayerHorrorMemory m){return switch(StoryChapter.forPlayer(m)){case ARRIVAL->.08;case ANOMALIES->.14;case SUSPICION->.22;case INVESTIGATION->.32;case NULL_INFLUENCE->.44;case DEEP_EXPLORATION->.58;};}
 @EventHandler public void onQuit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();PlayerHorrorMemory m=memories.remove(id);lastLocations.remove(id);behaviorCooldowns.remove(id);if(m!=null)store.save(id,m);}
 private boolean has(String t,String...terms){for(String s:terms)if(t.contains(s))return true;return false;}
}